p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--mode',choices=['engineering','diagnostics','e1','e2release','e2'],required=True);a=p.parse_args();r=a.root;c,lk=contract(r);stamp=lambda:datetime.datetime.now(datetime.timezone.utc).isoformat()

