def verify_predictions(folder,targets):
 done=read(folder/'complete.json');assert done['complete']and done['execution_lock_sha256']==lk
 assert [x['target_id']for x in done['records']]==[t['target_id']for t in targets]
 for x in done['records']:
  if x['status']=='ok':assert sha(folder/'predictions'/f"{x['target_id']}.npz")==x['prediction_sha256']
 return done

def score_jobs(jobs,out,secondary):
 out.mkdir(parents=True,exist_ok=True);refs={};fn=load_reference_lddt(r/'data/alphafold_lddt.py')
 for _,t,_,_ in jobs:
  tid=t['target_id']
  if tid not in refs:
   _,atoms=read_atom_site_positions(r/'data'/f'{tid}.cif.gz',label_asym_id=t['source_label_asym_id']);ref={i:v for(i,n),v in atoms.items()if n=='CA'}
   if'reference_ca_indices'in t:assert sorted(ref)==t['reference_ca_indices']
   refs[tid]=ref
 def calc(job):
  name,t,rec,path=job;tid=t['target_id'];base=dict(system=name,target_id=tid,status=rec['status'])
  if rec['status']!='ok':return dict(**base,ca_lddt=0.,residue_ca_lddt=0.,tm_score_fixed_full_length=0.,error=rec.get('error'))
  assert sha(path)==rec['prediction_sha256'];d=np.load(path);assert str(d['sequence'])==t['sequence'];xyz=d['coordinates'];mask=d['mask'];assert np.isfinite(xyz).all()and xyz.shape==(len(t['sequence']),37,3)
  pred={i+1:v for i,v in enumerate(xyz[:,1])if mask[i,1]};ref=refs[tid];ids=sorted(ref);assert all(i in pred for i in ids)
  pair=fixed_mask_metrics(ref,pred)['ca_lddt'];px=np.stack([pred[i]for i in ids]).astype('float64');rx=np.stack([ref[i]for i in ids]).astype('float64');m=np.ones((1,len(ids),1))
  assert abs(pair-float(fn(px[None],rx[None],m)[0]))<1e-6
  result=dict(**base,ca_lddt=pair,prediction_sha256=sha(path))
  if secondary:
   folder=out/'coordinates'/name/tid;folder.mkdir(parents=True,exist_ok=True);rp=folder/'ref.pdb';pp=folder/'pred.pdb';rp.write_text(ca_pdb(ref));pp.write_text(ca_pdb({i:pred[i]for i in ids}))
   tm=subprocess.run([str(r/'data/TMscore'),str(pp),str(rp),'-l',str(len(t['sequence']))],capture_output=True,text=True,check=True);(folder/'tm.txt').write_text(tm.stdout+tm.stderr)
   result.update(residue_ca_lddt=float(fn(px[None],rx[None],m,per_residue=True).mean()),tm_score_fixed_full_length=parse_tm_score(tm.stdout))
  return result
 with ThreadPoolExecutor(max_workers=8)as pool:rows=list(pool.map(calc,jobs))
 write(out/'metric_records.json',rows);return rows

def baseline_jobs(targets):
 jobs=[]
 for name,b in c['baselines'].items():
  assert sha(b['evaluation'])==b['evaluation_sha256'];by={x['target_id']:x for x in b['predictions']}
  for t in targets:
   x=by[t['target_id']];jobs.append((name,t,dict(status='ok',prediction_sha256=x['sha256']),Path(x['path'])))
 return jobs

def model_jobs(stage,runs,targets):
 jobs=[]
 for run in runs:
  folder=r/stage/'formal'/run['name'];done=verify_predictions(folder,targets);training=read(folder/'training_complete.json');assert training['steps']==1536 and training['execution_lock_sha256']==lk and sha(folder/'checkpoint_1536.pt')==training['checkpoint_sha256']
  jobs.extend((run['name'],t,rec,folder/'predictions'/f"{t['target_id']}.npz")for t,rec in zip(targets,done['records'],strict=True))
 return jobs

if a.mode=='engineering':
 inputs={}
 for i in range(2):
  f=r/'engineering'/f'smoke_{i}.json';x=read(f);assert x['passed']and x['execution_lock_sha256']==lk and len(x['checks'])==8;inputs[str(f)]=sha(f)
 write(r/'engineering/e1_passed.json',dict(passed=True,execution_lock_sha256=lk,inputs=inputs,utc=stamp()));raise SystemExit

if a.mode=='diagnostics':
 assert not(r/'e1/formal').exists(),'Formal training must follow prediction seal'
 X=np.zeros((8,3));raw=[];inputs={}
 for j,rid in enumerate(c['rotation_ids']):
  for k,s in enumerate(c['formal_seeds']):
   name=f'{rid}_s{s}';folder=r/'e1/probes'/name;done=read(folder/'complete.json');assert done['complete']and done['steps']==768 and done['execution_lock_sha256']==lk
   for f,h in done['artifacts'].items():assert sha(folder/f)==h
   inputs[str(folder/'complete.json')]=sha(folder/'complete.json');ev=read(folder/'evaluation_768.json');v=[x for x in ev['records']if x['split']=='holdout72'];assert len(v)==72 and all(len(x['rounds'])==4 for x in v)
   X[j,k]=np.mean([x['mean_relative_error']for x in v]);raw.append(dict(rotation=rid,teacher_seed=s,mean_error=float(X[j,k]),zero_reference=float(np.mean([x['mean_zero_output_error']for x in v])),norm_ratio=float(np.mean([y['norm_ratio']for x in v for y in x['rounds']])),cosine=float(np.mean([y['cosine']for x in v for y in x['rounds']]))))
 dev=read(r/'data/dev8.json')['targets'];jobs=[]
 for rid in ['I',*c['rotation_ids']]:
  for s in c['formal_seeds']:
   folder=r/'diagnostics/dev'/f'{rid}_s{s}';done=verify_predictions(folder,dev);assert not done['failures'];inputs[str(folder/'complete.json')]=sha(folder/'complete.json')
   jobs.extend((f'{rid}_s{s}',t,rec,folder/'predictions'/f"{t['target_id']}.npz")for t,rec in zip(dev,done['records'],strict=True))
 rows=score_jobs(jobs,r/'diagnostics/analysis',False);values={(x['system'],x['target_id']):x['ca_lddt']for x in rows}
 D=np.array([[np.mean([values[f'I_s{s}',t['target_id']]-values[f'{rid}_s{s}',t['target_id']]for t in dev])for s in c['formal_seeds']]for rid in c['rotation_ids']]);xm=X.mean(1);dm=D.mean(1)
 assert np.isfinite(X).all()and np.isfinite(D).all();valid=float(np.ptp(xm))>c['X_min_span'];order=sorted(range(8),key=lambda i:(xm[i],c['rotation_ids'][i]));do=sorted(range(8),key=lambda i:(dm[i],c['rotation_ids'][i]))
 result=dict(execution_lock_sha256=lk,released=valid,utc=stamp(),X=xm.tolist(),D=dm.tolist(),X_by_teacher=X.tolist(),D_by_teacher=D.tolist(),rotation_ids=c['rotation_ids'],X_ascending=[c['rotation_ids'][i]for i in order],D_ascending=[c['rotation_ids'][i]for i in do],selected_low=c['rotation_ids'][order[0]],selected_high=c['rotation_ids'][order[-1]],X_span=float(np.ptp(xm)),X_min_span=c['X_min_span'],leave_one_teacher_X=[X[:,[k for k in range(3)if k!=drop]].mean(1).tolist()for drop in range(3)],inputs=inputs,probe_summaries=raw,structure_training_started=False,scope='Prospective configuration diagnosis on observed Train/Dev; no new target confirmation')
 write(r/'prediction_lock.json',result)
 lines=['# E1正式结构训练前的诊断封存','','X唯一主要候选；D是竞争探索候选。高低R只由X选定。','','|旋转|X：重建误差|D：Dev即时损害|','|---|---:|---:|']
 for j,rid in enumerate(c['rotation_ids']):lines.append(f'|{rid}|{xm[j]:.8f}|{dm[j]:+.8f}|')
 lines+=['',f"X最低：{result['selected_low']}；最高：{result['selected_high']}。可分辨性释放：{valid}。",'',f'时间：{result["utc"]}。测试对象是已观察Confirm96-B上的新旋转配置，不是新目标确认。']
 (r/'diagnostics/predictions.md').write_text('\n'.join(lines)+'\n')
 if not valid:raise RuntimeError('X is not measurably varying; no E1/E2 formal release')
 raise SystemExit

if a.mode=='e2release':
 pred=read(r/'prediction_lock.json');done=read(r/'e1/analysis/complete.json');assert done['complete']and done['execution_lock_sha256']==lk and pred['released']
 assert c['E2_independent_authorized']
 runs=[dict(name=f'{rid}_C_s{s}',rotation_id=rid,seed=s,steps=1536,kind='factor_plus_shared_C')for rid in ['I',pred['selected_low'],pred['selected_high']]for s in c['formal_seeds']]
 write(r/'e2_execution_lock.json',dict(execution_lock_sha256=lk,released=True,utc=stamp(),runs=runs,prediction_lock_sha256=sha(r/'prediction_lock.json'),e1_completion_sha256=sha(r/'e1/analysis/complete.json'),independent_intervention_authorized=True,outcome_positive_not_required=True));raise SystemExit

stage=a.mode;targets=[t for t in read(r/'data/evaluation144.json')['targets']if t['panel']=='confirm96'];ids=[t['target_id']for t in targets];pred=read(r/'prediction_lock.json');assert pred['released'];out=r/stage/'analysis'
if stage=='e1':jobs=model_jobs('e1',c['new_runs'],targets)+baseline_jobs(targets)
else:
 rel=read(r/'e2_execution_lock.json');jobs=model_jobs('e2',rel['runs'],targets)
rows=score_jobs(jobs,out,True)
assert len(rows)==(2688 if stage=='e1'else 864)
new_names={x['name']for x in(c['new_runs']if stage=='e1'else rel['runs'])}
new_failures=sum(x['status']!='ok'for x in rows if x['system']in new_names)
if stage=='e2':rows+=read(r/'e1/analysis/metric_records.json')
values={(x['system'],x['target_id']):x for x in rows};assert len(values)==len(rows)
seeds=c['formal_seeds'];draw=np.random.default_rng(20260924).integers(96,size=(20000,96))
