def summary(x):
 di=np.asarray(x).mean(0);return dict(mean=float(di.mean()),ci95=np.quantile(di[draw].mean(1),[.025,.975]).tolist(),per_target=di.tolist(),per_seed=np.asarray(x).mean(-1).tolist())
result=dict(execution_lock_sha256=lk,prediction_lock_sha256=sha(r/'prediction_lock.json'),utc=stamp(),stage=stage,scope='Observed Confirm96-B; E1 independent prediction units are eight rotations; E2 is a paired intervention on two selected rotations',new_failures=new_failures,failures=sum(x['status']!='ok'for x in rows),metrics={})
for metric in ['ca_lddt','residue_ca_lddt','tm_score_fixed_full_length']:
 N=np.stack([vec(f'native_s{s}',metric)for s in seeds]);Q=vec('query',metric)
 if stage=='e1':
  R=np.stack([[vec(f'{rid}_s{s}',metric)for s in seeds]for rid in c['rotation_ids']]);delta=N[None]-R;Y=delta.mean((1,2));row=dict(native_mean=float(N.mean()),query_mean=float(Q.mean()),rotated_means=R.mean((1,2)).tolist(),Y=Y.tolist(),rotation_costs={rid:summary(delta[j])for j,rid in enumerate(c['rotation_ids'])},native_minus_query=summary(N-Q),rotated_minus_query={rid:summary(R[j]-Q)for j,rid in enumerate(c['rotation_ids'])})
  if metric=='ca_lddt':
   row['X_test']=exact_rotation_test(pred['X'],Y);row['D_exploratory_test']=exact_rotation_test(pred['D'],Y)
   row['per_training_seed']=[dict(seed=s,X_rho=spearman(pred['X'],delta[:,k].mean(1)),D_rho=spearman(pred['D'],delta[:,k].mean(1)))for k,s in enumerate(seeds)]
   row['leave_one_teacher_X_rho']=[spearman(x,Y)for x in pred['leave_one_teacher_X']]
   # Synchronized target bootstrap is conditional sensitivity, not n=96 rotation testing.
   correlations=[];dm=delta.mean(1);xr=average_ranks(pred['X']);xr-=xr.mean()
   for d in np.array_split(draw,40):
    ys=dm[:,d].mean(2).T;rank=1+(ys[:,:,None]>ys[:,None,:]).sum(2)+.5*((ys[:,:,None]==ys[:,None,:]).sum(2)-1);rank-=rank.mean(1,keepdims=True);den=np.linalg.norm(rank,axis=1)*np.linalg.norm(xr);correlations.extend(np.divide(rank@xr,den,out=np.full(len(den),np.nan),where=den>0).tolist())
   cs=np.asarray(correlations);row['target_bootstrap_X_rho']=dict(ci95=np.quantile(cs[np.isfinite(cs)],[.025,.975]).tolist()if np.isfinite(cs).any()else None,constant_outcome_draws=int((~np.isfinite(cs)).sum()),draws=20000)
  result['metrics'][metric]=row
 else:
  Nc=np.stack([vec(f'I_C_s{s}',metric)for s in seeds]);Rs=[pred['selected_low'],pred['selected_high']];fixed=np.stack([[vec(f'{rid}_s{s}',metric)for s in seeds]for rid in Rs]);learned=np.stack([[vec(f'{rid}_C_s{s}',metric)for s in seeds]for rid in Rs]);tc=(N[None]-fixed)-(Nc[None]-learned);br=learned-fixed
  result['metrics'][metric]=dict(T_C=summary(tc.mean(0)),B_R=summary(br.mean(0)),native_change=summary(Nc-N),per_rotation={rid:dict(T_C=summary(tc[j]),B_R=summary(br[j]),fixed_mean=float(fixed[j].mean()),learned_mean=float(learned[j].mean()))for j,rid in enumerate(Rs)},native_fixed=float(N.mean()),native_learned=float(Nc.mean()),query_mean=float(Q.mean()))
